"}\n"
"\n"
".crumb { min-width: 0; }\n"
".crumb h1 { font-size: 15px; font-weight: 600; letter-spacing: -.1px; }\n"
".crumb-sub { font-size: 11px; color: var(--muted); margin-top: 1px; }\n"
"\n"
"/* The status strip: the few facts worth seeing on every page. */\n"
".sysbar { display: flex; gap: 18px; margin-left: auto; align-items: center; }\n"
".sys-item { display: flex; flex-direction: column; line-height: 1.2; }\n"
".sys-item .v { font-size: 12.5px; font-weight: 600; font-family: var(--mono); }\n"
".sys-item .k {\n"
"    font-size: 9px; color: var(--muted);\n"
"    letter-spacing: .8px; text-transform: uppercase;\n"
"}\n"
".sys-item .v.ok { color: var(--ok); }\n"
".sys-item .v.bad { color: var(--danger); }\n"
".sys-item .v.warn { color: var(--warn); }\n"
"\n"
".session {\n"
"    display: flex; align-items: center; gap: 10px;\n"
"    padding-left: 16px; border-left: 1px solid var(--line);\n"
"}\n"
".configbar { display: flex; gap: 6px; }\n"
".whoami { font-size: 11.5px; color: var(--text-dim); white-space: nowrap; }\n"
"\n"
"/* \342\224\200\342\224\200 transport and unsaved state \342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200 */\n"
"\n"
"/* Both read as status, so both use the status colours and neither uses the\n"
"   brand colour -- that one is reserved for the current selection and the\n"
"   primary action, and an indicator competing with it would make the page\n"
"   harder to scan at exactly the moment it matters. */\n"
".conn, .unsaved {\n"
"    font-size: 10.5px; font-weight: 600; letter-spacing: .04em;\n"
"    text-transform: uppercase; white-space: nowrap;\n"
"    padding: 3px 8px; border-radius: 4px; border: 1px solid transparent;\n"
"}\n"
".conn.ok  { color: var(--ok);     background: var(--ok-bg);     border-color: var(--ok-line); }\n"
".conn.bad { color: var(--danger); background: var(--danger-bg); border-color: var(--danger-line); }\n"
"\n"
"/* Amber, not red: unsaved is a state to resolve, not a fault. Red here\n"
"   would train the operator to read red as \"normal\", which costs the one\n"
"   place it has to mean something. */\n"
".unsaved {\n"
"    color: var(--warn); background: var(--warn-bg); border-color: var(--warn-line);\n"
"}\n"
"\n"
"main { padding: 18px 20px 40px; flex: 1 1 auto; }\n"
"\n"
"/* \342\224\200\342\224\200 page furniture \342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200 */\n"
"\n"
".page-head {\n"
"    display: flex; justify-content: space-between; align-items: flex-start;\n"
"    gap: 14px; margin-bottom: 16px; flex-wrap: wrap;\n"
"}\n"
".page-head h1 { font-size: 16px; font-weight: 600; }\n"
".page-head .sub { font-size: 11.5px; color: var(--muted); margin-top: 2px; }\n"
".head-actions { display: flex; gap: 8px; flex-wrap: wrap; }\n"
"\n"
".ro-badge {\n"
"    font-size: 9.5px; font-weight: 700; letter-spacing: 1px;\n"
"    padding: 4px 9px; border-radius: var(--radius);\n"
"    background: var(--warn-bg); color: var(--warn);\n"
"    border: 1px solid var(--warn-line); text-transform: uppercase;\n"
"}\n"
"\n"
"/* \342\224\200\342\224\200 cards \342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200 */\n"
"\n"
".panel {\n"
"    background: var(--surface);\n"
"    border: 1px solid var(--line);\n"
"    border-radius: var(--radius-lg);\n"
"    margin-bottom: 14px;\n"
"    overflow: hidden;\n"
"}\n"
".panel > h3 {\n"
"    font-size: 12px; font-weight: 600; letter-spacing: .2px;\n"
"    padding: 11px 14px;\n"
"    border-bottom: 1px solid var(--line);\n"
"    background: var(--surface-2);\n"
"    display: flex; align-items: center; gap: 8px;\n"
"}\n"
".panel > h3 .right { margin-left: auto; font-weight: 400; color: var(--muted);\n"
"                     font-size: 11px; }\n"
"/* Content that is not a table gets the padding; tables sit flush. */\n"
".panel > *:not(h3):not(table):not(.tw) { padding: 0 14px; }\n"
".panel > *:not(h3):not(table):not(.tw):first-of-type { padding-top: 14px; }\n"
".panel > *:not(h3):not(table):not(.tw):last-child { padding-bottom: 14px; }\n"
".tw { overflow-x: auto; }\n"
"\n"
"/* \342\224\200\342\224\200 KPI tiles \342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200 */\n"
"\n"
".kpi-row {\n"
"    display: grid;\n"
"    grid-template-columns: repeat(auto-fit, minmax(146px, 1fr));\n"
"    gap: 10px; margin-bottom: 14px;\n"
"}\n"
".kpi {\n"
"    background: var(--surface);\n"
"    border: 1px solid var(--line);\n"
"    border-radius: var(--radius-lg);\n"
"    padding: 12px 14px;\n"
"    position: relative;\n"
"}\n"
".kpi-n { font-size: 22px; font-weight: 650; letter-spacing: -.5px;\n"
"         font-family: var(--mono); line-height: 1.2; }\n"
".kpi-l { font-size: 9.5px; color: var(--muted); letter-spacing: 1px;\n"
"         text-transform: uppercase; margin-top: 3px; }\n"
".kpi-sub { font-size: 11px; color: var(--text-dim); margin-top: 5px; }\n"
".kpi.ok     .kpi-n { color: var(--ok); }\n"
".kpi.danger .kpi-n { color: var(--danger); }\n"
".kpi.warn   .kpi-n { color: var(--warn); }\n"
".kpi.info   .kpi-n { color: var(--info); }\n"
"/* A tile that is reporting a fault earns a left edge, so a wall of tiles\n"
" * still has one obvious place to look. */\n"
".kpi.danger { border-left: 2px solid var(--danger); }\n"
".kpi.warn   { border-left: 2px solid var(--warn); }\n"
"\n"
"/* \342\224\200\342\224\200 tables \342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200 */\n"
"\n"
".dt { width: 100%; border-collapse: collapse; }\n"
".dt th {\n"
"    background: var(--surface-2);\n"
"    padding: 8px 14px; text-align: left;\n"
"    font-size: 9.5px; font-weight: 700; letter-spacing: 1px;\n"
"    text-transform: uppercase; color: var(--muted);\n"
"    white-space: nowrap; border-bottom: 1px solid var(--line);\n"
"}\n"
".dt td {\n"
"    padding: 8px 14px; border-top: 1px solid var(--line-soft);\n"
"    font-size: 12.5px; vertical-align: middle;\n"
"}\n"
".dt tbody tr:hover td { background: var(--surface-2); }\n"
".dt td.num, .dt th.num { text-align: right; font-variant-numeric: tabular-nums; }\n"
".dt .sub { font-size: 11px; color: var(--muted); }\n"
"\n"
".mono  { font-family: var(--mono); font-size: 12px; font-variant-numeric: tabular-nums; }\n"
".small { font-size: 11.5px; }\n"
".muted { color: var(--muted); }\n"
".ok    { color: var(--ok); }\n"
".no    { color: var(--danger); }\n"
".warn  { color: var(--warn); }\n"
".danger{ color: var(--danger); }\n"
"\n"
".empty { padding: 26px 14px; text-align: center; color: var(--muted);\n"
"         font-size: 12px; }\n"
"\n"
"/* \342\224\200\342\224\200 status chips \342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200 */\n"
"\n"
".pill {\n"
"    display: inline-block; padding: 2px 8px; border-radius: var(--radius);\n"
"    font-size: 10px; font-weight: 700; letter-spacing: .5px;\n"
"    text-transform: uppercase; white-space: nowrap;\n"
"    border: 1px solid transparent;\n"
"}\n"
".pill.ok   { background: var(--ok-bg);     border-color: var(--ok-line);     color: var(--ok); }\n"
".pill.bad  { background: var(--danger-bg); border-color: var(--danger-line); color: var(--danger); }\n"
".pill.warn { background: var(--warn-bg);   border-color: var(--warn-line);   color: var(--warn); }\n"
".pill.info { background: var(--info-bg);   border-color: var(--info-line);   color: var(--info); }\n"
".pill.mut  { background: var(--raised);    border-color: var(--line);        color: var(--muted); }\n"
"\n"
"/* A dot for inline state, where a chip would be too loud in a dense row. */\n"
".dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%;\n"
"       margin-right: 7px; vertical-align: 0; background: var(--muted); }\n"
".dot.ok { background: var(--ok); box-shadow: 0 0 0 2px rgba(34,197,94,.18); }\n"
".dot.bad { background: var(--danger); box-shadow: 0 0 0 2px rgba(244,63,94,.18); }\n"
".dot.warn { background: var(--warn); box-shadow: 0 0 0 2px rgba(245,158,11,.18); }\n"
"\n"
".zone-chip {\n"
"    display: inline-block; padding: 2px 8px; border-radius: var(--radius);\n"
"    font-size: 10px; font-weight: 700; letter-spacing: .5px;\n"
"    background: color-mix(in srgb, var(--zc) 15%, transparent);\n"
"    color: var(--zc);\n"
"    border: 1px solid color-mix(in srgb, var(--zc) 40%, transparent);\n"
"}\n"
"\n"
".mode-chip { padding: 2px 8px; border-radius: var(--radius);\n"
"             font-size: 10px; font-weight: 700; letter-spacing: .5px; }\n"
".mode-access   { background: var(--ok-bg);   color: var(--ok); }\n"
".mode-trunk    { background: var(--warn-bg); color: var(--warn); }\n"
".mode-hybrid   { background: #241A33;        color: #A78BFA; }\n"
".mode-mirror   { background: var(--info-bg); color: var(--info); }\n"
".mode-disabled { background: var(--raised);  color: var(--muted); }\n"
"\n"
".sev { display: inline-block; min-width: 20px; height: 20px; line-height: 20px;\n"
"       text-align: center; border-radius: var(--radius);\n"
"       font-size: 10.5px; font-weight: 700; font-family: var(--mono); }\n"
".sev.s1 { background: var(--raised);    color: var(--muted); }\n"
".sev.s2 { background: var(--warn-bg);   color: var(--warn); }\n"
".sev.s3 { background: #33200C;          color: #FB923C; }\n"
".sev.s4 { background: var(--danger-bg); color: var(--danger); }\n"
"\n"
".active-pill {\n"
"    font-size: 9px; font-weight: 700; letter-spacing: .8px;\n"
"    padding: 1px 6px; border-radius: var(--radius); vertical-align: 1px;\n"
"    background: var(--ok-bg); color: var(--ok); border: 1px solid var(--ok-line);\n"
"}\n"
"\n"
".role-badge { font-size: 10px; font-weight: 700; letter-spacing: .6px;\n"
"              padding: 3px 8px; border-radius: var(--radius);\n"
"              text-transform: uppercase; }\n"
".role-badge.admin { background: var(--ok-bg); color: var(--ok);\n"
"                    border: 1px solid var(--ok-line); }\n"
"\n"
"/* \342\224\200\342\224\200 buttons \342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200 */\n"
"\n"
".mini {\n"
"    font: inherit; font-size: 11.5px; font-weight: 500;\n"
"    padding: 6px 11px; border-radius: var(--radius); cursor: pointer;\n"
"    border: 1px solid var(--line); background: var(--raised);\n"
"    color: var(--text-dim); text-decoration: none;\n"
"    display: inline-flex; align-items: center; gap: 6px; line-height: 1.3;\n"
"    white-space: nowrap;\n"
"}\n"
".mini:hover:not(:disabled) { border-color: #31405A; background: #202838;\n"
"                             color: var(--text); }\n"
".mini:disabled { opacity: .45; cursor: default; }\n"
".mini.primary { background: var(--brand); border-color: var(--brand);\n"
"                color: #fff; font-weight: 600; }\n"
".mini.primary:hover:not(:disabled) { background: #FF5E42; border-color: #FF5E42; }\n"
".mini.warn { background: var(--warn-bg); border-color: var(--warn-line);\n"
"             color: var(--warn); }\n"
".mini.warn:hover:not(:disabled) { background: #3A2B0C; }\n"
".mini.bad  { background: var(--danger-bg); border-color: var(--danger-line);\n"
"             color: var(--danger); }\n"
".mini.bad:hover:not(:disabled) { background: #3A1019; }\n"
".mini.ghost { background: transparent; }\n"
".mini.on { border-color: var(--ok-line); background: var(--ok-bg); color: var(--ok); }\n"
"\n"
".btn-row { display: flex; gap: 8px; flex-wrap: wrap; }\n"
"\n"
"/* \342\224\200\342\224\200 forms \342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200 */\n"
"\n"
"label.fld { display: flex; flex-direction: column; gap: 5px;\n"
"            font-size: 10.5px; color: var(--muted);\n"
"            letter-spacing: .6px; text-transform: uppercase; }\n"
"input, select, textarea {\n"
"    font: inherit; font-size: 12.5px;\n"
"    padding: 7px 10px; border-radius: var(--radius);\n"
"    border: 1px solid var(--line); background: var(--bg); color: var(--text);\n"
"}\n"
"input:focus, select:focus, textarea:focus {\n"
"    outline: none; border-color: var(--brand);\n"
"    box-shadow: 0 0 0 2px rgba(255,75,43,.15);\n"
"}\n"
"input::placeholder { color: #4A5667; }\n"
"\n"
".capform, .pwform { display: flex; flex-wrap: wrap; gap: 10px;\n"
"                    align-items: flex-end; }\n"
".capform label, .pwform label {\n"
"    display: flex; flex-direction: column; gap: 5px;\n"
"    font-size: 10.5px; color: var(--muted); letter-spacing: .6px;\n"
"    text-transform: uppercase;\n"
"}\n"
".capform input, .capform select { width: 150px; }\n"
".pwform select { min-width: 150px; }\n"
".pwform input { width: 190px; }\n"
"\n"
"/* \342\224\200\342\224\200 zone matrix \342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200 */\n"
"\n"
".matrix { border-collapse: separate; border-spacing: 3px; margin: 12px 0 0; }\n"
".matrix th {\n"
"    font-size: 9.5px; font-weight: 700; letter-spacing: .8px;\n"
"    padding: 7px 10px; background: var(--surface-2);\n"
"    border-radius: var(--radius); color: var(--zc, var(--text));\n"
"}\n"
".matrix th.corner { background: transparent; color: var(--muted); font-size: 9px; }\n"
".matrix td {\n"
"    width: 48px; height: 36px; text-align: center;\n"
"    border-radius: var(--radius); font-size: 14px; font-weight: 700;\n"
"    user-select: none;\n"
"}\n"
".m-allow { background: var(--ok-bg);     color: var(--ok); }\n"
".m-log   { background: var(--warn-bg);   color: var(--warn); }\n"
".m-deny  { background: var(--danger-bg); color: var(--danger); }\n"
".m-self  { background: var(--surface-2); color: #3A4557; }\n"
"td.editable { cursor: pointer; }\n"
"td.editable:hover { outline: 2px solid var(--brand); outline-offset: -2px; }\n"
"\n"
".legend { display: flex; gap: 16px; margin-top: 12px; font-size: 11.5px;\n"
"          color: var(--muted); flex-wrap: wrap; }\n"
".legend i { display: inline-block; width: 12px; height: 12px;\n"
"            border-radius: 3px; margin-right: 6px; vertical-align: -2px; }\n"
".legend .m-allow { border: 1px solid var(--ok-line); }\n"
".legend .m-log   { border: 1px solid var(--warn-line); }\n"
".legend .m-deny  { border: 1px solid var(--danger-line); }\n"
"\n"
"/* \342\224\200\342\224\200 misc \342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200 */\n"
"\n"
".spark { display: block; }\n"
".sparkcell { width: 230px; padding: 3px 14px !important; }\n"
"\n"
".planbox {\n"
"    margin: 10px 0; padding: 12px; border-radius: var(--radius);\n"
"    background: var(--bg); border: 1px solid var(--line);\n"
"    font-family: var(--mono); font-size: 11.5px; line-height: 1.65;\n"
"    color: var(--text-dim); overflow-x: auto; white-space: pre;\n"
"    max-height: 340px;\n"
"}\n"
"details summary { cursor: pointer; }\n"
"details summary::-webkit-details-marker { color: var(--muted); }\n"
"\n"
"/* The one panel allowed to shout. It is rendered only while a shipped\n"
" * password is still live, which is a fault the operator has to see. */\n"
".danger-panel { border-color: var(--danger-line); }\n"
".danger-panel > h3 { background: var(--danger-bg); color: #FF8899; }\n"
"\n"
".note {\n"
"    font-size: 11.5px; color: var(--text-dim);\n"
"    background: var(--surface-2); border-left: 2px solid var(--line);\n"
"    padding: 9px 12px; border-radius: var(--radius); margin: 10px 0;\n"
"}\n"
".note.info { border-left-color: var(--info); }\n"
".note.warn { border-left-color: var(--warn); }\n"
".note.bad  { border-left-color: var(--danger); }\n"
"\n"
"/* \342\224\200\342\224\200 login \342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200 */\n"
"\n"
".login-wrap { display: flex; justify-content: center; padding: 64px 16px; }\n"
".login {\n"
"    width: 100%; max-width: 330px; display: flex; flex-direction: column;\n"
"    gap: 14px; background: var(--surface); border: 1px solid var(--line);\n"
"    border-radius: var(--radius-lg); padding: 26px;\n"
"}\n"
".login h2 { font-size: 17px; font-weight: 600; }\n"
".login label { display: flex; flex-direction: column; gap: 6px;\n"
"               font-size: 10.5px; color: var(--muted);\n"
"               letter-spacing: .6px; text-transform: uppercase; }\n"
".login button { padding: 10px; border-radius: var(--radius); border: 0;\n"
"                cursor: pointer; font-weight: 600; font-size: 13px;\n"
"                background: var(--brand); color: #fff; }\n"
".login .no { min-height: 1em; font-size: 12px; }\n"
"\n"
"/* \342\224\200\342\224\200 toast \342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200 */\n"
"\n"
".toast {\n"
"    position: fixed; left: 50%; bottom: 26px; transform: translate(-50%, 14px);\n"
"    background: #14532D; color: #D7FBE4; border: 1px solid var(--ok-line);\n"
"    padding: 10px 18px; border-radius: var(--radius);\n"
"    font-size: 12.5px; max-width: min(560px, 90vw);\n"
"    opacity: 0; pointer-events: none; transition: opacity .16s, transform .16s;\n"
"    z-index: 60;\n"
"}\n"
".toast.bad { background: #4C1020; border-color: var(--danger-line); color: #FFD6DE; }\n"
".toast.show { opacity: 1; transform: translate(-50%, 0); }\n"
"\n"
"/* \342\224\200\342\224\200 responsive \342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200 */\n"
"\n"
"@media (max-width: 1100px) {\n"
"    .sysbar .sys-item.opt { display: none; }\n"
"}\n"
"@media (max-width: 860px) {\n"
"    .side {\n"
"        position: fixed; left: 0; top: 0; z-index: 40;\n"
"        transform: translateX(-100%); transition: transform .18s;\n"
"    }\n"
"    .side.open { transform: none; }\n"
"    .side-toggle { display: inline-flex; }\n"
"    .sysbar { display: none; }\n"
"    main { padding: 14px; }\n"
"    .session { padding-left: 10px; }\n"
"}\n"
"";

